/**
 * @summary List knowledge chunks
 */
export const getListChunksUrl = (params?: ListChunksParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/rag/chunks?${stringifiedParams}`
    : `/api/rag/chunks`;
};

export const listChunks = async (
  params?: ListChunksParams,
  options?: RequestInit,
): Promise<KnowledgeChunk[]> => {
  return customFetch<KnowledgeChunk[]>(getListChunksUrl(params), {
    ...options,
    method: "GET",
  });
};

